-- ZeD-UI/42/media/lua/client/ZeD/ZeD_Watch.lua
-- ============================================================================
-- CAZIO WATCH v5 (S123) — a physical wristwatch at the top-right, built from
-- plates + live overlays. Replaces the Java clock AND the Java speed controls.
--
-- Design: ZeDUI/mockups/zed_cazio_watch_v5_round.html (locked Oct 12 2026).
-- Plates: 42/media/textures/ZeD/watch/*.png (2x) generated by
-- ZeDUI/tools/plates/plates_watch.html; anchors in WatchPlates.lua.
--
-- Families and controls (same four actions on every one):
--   digital  (A120 style): LCD + two coloured front keys (ALARM, SET) + two metal
--            keys (SPEED steps 1x 2x 3x, START/STOP pauses)
--   classic  (round ana-digi): hands + LCD window; side pushers SET, SPEED,
--            ALARM, START + crown (= alarm)
--   expensive (round, fluted bezel): hands + date; pushers START, SPEED; crown = alarm
--   no watch: the plain speed strip only (vanilla keeps speed controls without a watch)
-- Alarm set mode: the LCD shows the alarm hour; click the left half for -1h,
-- the right half for +1h, SET (or the crown) closes.
-- ============================================================================

require "ZeD/ZeD_Panel"
require "ZeD/WatchPlates"

ZeD = ZeD or {}
ZeD.Watch = ZeD.Watch or {}
local W = ZeD.Watch
local PL = ZeD.WatchPlates
local TEXDIR = "media/textures/ZeD/watch/"
W.scale = W.scale or 1.0
W.dressVariant = W.dressVariant or "dress"   -- "dress" (steel) or "gold" (director's call)

local function _safe(fn, default) local ok, v = pcall(fn); if ok then return v end; return default end
local function hex(h)
    h = tostring(h or "#ffffff"):gsub("#", "")
    return { r = (tonumber(h:sub(1,2), 16) or 255)/255, g = (tonumber(h:sub(3,4), 16) or 255)/255, b = (tonumber(h:sub(5,6), 16) or 255)/255, a = 1 }
end
local _cc = {}
local function col(c) if type(c) == "table" then return c end; local v = _cc[c]; if not v then v = hex(c); _cc[c] = v end; return v end
local _texCache = {}
local function tex(path) local t = _texCache[path]; if t == nil then t = getTexture(path) or false; _texCache[path] = t end; return t or nil end

local DAYS = { "SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT" }
local MONTHS = { "JAN", "FEB", "MAR", "APR", "MAY", "JUN", "JUL", "AUG", "SEP", "OCT", "NOV", "DEC" }
local function _dayOfWeek(y, m, d)   -- Zeller, 1 = Sunday
    if m < 3 then m = m + 12; y = y - 1 end
    local k, j = y % 100, math.floor(y / 100)
    local h = (d + math.floor(13 * (m + 1) / 5) + k + math.floor(k / 4) + math.floor(j / 4) + 5 * j) % 7
    return ((h + 6) % 7) + 1
end
local function _timeInfo()
    local gt = getGameTime()
    local hour, min = gt:getHour(), gt:getMinutes()
    local fmt24 = true
    local ok24, v24 = pcall(function() return getCore():getOptionClock24Hour() end)
    if ok24 and v24 == false then fmt24 = false end
    local monthFirst = true
    local okF, f = pcall(function() return getCore():getOptionClockFormat() end)
    if okF and f == 2 then monthFirst = false end
    local timeStr, pm = nil, false
    if fmt24 then timeStr = string.format("%02d:%02d", hour, min)
    else local h12 = hour % 12; if h12 == 0 then h12 = 12 end; timeStr = string.format("%d:%02d", h12, min); pm = hour >= 12 end
    local day = (gt:getDay() or 0) + 1
    local month = (gt:getMonth() or 0) + 1
    local year = gt:getYear() or 1993
    local dow = DAYS[_dayOfWeek(year, month, day)] or ""
    local dateShort = monthFirst and string.format("%d-%d", month, day) or string.format("%d-%d", day, month)
    return { hour = hour, min = min, timeStr = timeStr, pm = pm, fmt24 = fmt24, dow = dow, day = day, dateShort = dateShort, month = MONTHS[month] or "" }
end
W._timeInfo = _timeInfo

-- ---------------------------------------------------------------------------
-- Worn watch -> plate
-- ---------------------------------------------------------------------------
local function _wornWatch(player)
    local worn = _safe(function() return player:getWornItems() end, nil)
    if not worn then return nil end
    for i = 0, worn:size() - 1 do
        local wi = worn:get(i)
        local item = wi and wi:getItem()
        if item and instanceof(item, "AlarmClockClothing") then
            local loc = tostring(wi:getLocation() or ""):lower()
            if loc:find("wrist") or loc == "" then return item end
        end
    end
    return nil
end
local function _plateFor(item)
    if not item then return nil end
    local ft = _safe(function() return tostring(item:getFullType()) end, "")
    if ft:find("DigitalBlack") then return "digital_black", "digital" end
    if ft:find("DigitalRed") then return "digital_red", "digital" end
    if ft:find("DigitalDress") then return "digital_" .. ((W.dressVariant == "gold") and "gold" or "dress"), "digital" end
    if ft:find("ClassicBlack") then return "classic_black", "classic" end
    if ft:find("ClassicBrown") then return "classic_brown", "classic" end
    if ft:find("ClassicGold") then return "classic_gold", "classic" end
    if ft:find("ClassicMilitary") then return "classic_military", "classic" end
    if ft:find("Expensive") then return "expensive", "expensive" end
    if _safe(function() return item:isDigital() end, true) then return "digital_black", "digital" end
    return "classic_black", "classic"
end

-- ---------------------------------------------------------------------------
-- Game speed through the Java speed controls (parked but still the authority)
-- ---------------------------------------------------------------------------
local function _speed() local sc = UIManager.getSpeedControls(); return sc and sc:getCurrentGameSpeed() or 1 end
local function _setSpeed(n)
    local sc = UIManager.getSpeedControls(); if not sc then return end
    if n <= 0 then pcall(function() sc:ButtonClicked("Pause") end); return end
    local ok = pcall(function() sc:SetCurrentGameSpeed(n) end)
    if not ok and n == 1 then pcall(function() sc:ButtonClicked("Play") end) end
end
W._lastRun = W._lastRun or 1
local function _actStart() local sp = _speed(); if sp == 0 then _setSpeed(W._lastRun or 1) else W._lastRun = sp; _setSpeed(0) end end
local function _actSpeed() local sp = _speed(); if sp == 0 then return end; local n = sp + 1; if n > 3 then n = 1 end; W._lastRun = n; _setSpeed(n) end

-- ---------------------------------------------------------------------------
-- The organism
-- ---------------------------------------------------------------------------
ZeD_Watch = ZeD_Panel:derive("ZeD_Watch")

function ZeD_Watch:new(playerNum)
    local o = ZeD_Panel:new(0, 0, 150, 176)
    setmetatable(o, self)
    self.__index = self
    o.playerNum = playerNum or 0
    o._zedLabel = "Watch"
    o._hit = {}
    o._s = 1
    o._setOpen = false
    o.backgroundColor = { r = 0, g = 0, b = 0, a = 0 }
    o.borderColor     = { r = 0, g = 0, b = 0, a = 0 }
    return o
end

function ZeD_Watch:_scale() local T = ZeD.T; return ((T and T.scale) or 1) * (W.scale or 1) end

function ZeD_Watch:_rect(x, y, w, h, c, a)
    local s = self._s; c = col(c)
    self:drawRect(math.floor(x * s), math.floor(y * s), math.max(1, math.floor(w * s)), math.max(1, math.floor(h * s)), a or c.a or 1, c.r, c.g, c.b)
end
function ZeD_Watch:_run(cx, cy, deg, r0, r1, c, thick)
    local s = self._s; c = col(c)
    local a = (deg - 90) * math.pi / 180
    local ca, sa = math.cos(a), math.sin(a)
    local t = math.max(1, math.floor((thick or 2) * s))
    local r, step = r0, 1 / s
    while r <= r1 do
        self:drawRect(math.floor((cx + ca * r) * s - t / 2), math.floor((cy + sa * r) * s - t / 2), t, t, c.a or 1, c.r, c.g, c.b)
        r = r + step
    end
end
local function fontFor(size)
    local T = ZeD.T
    if (size or 5) >= 13 then return T.fontF4 end
    if (size or 5) >= 7 then return T.fontF3 end
    return T.fontF5
end
function ZeD_Watch:_text(x, y, str, size, c, align)
    local s = self._s; c = col(c); local f = fontFor(size)
    local tm = getTextManager(); local w = tm:MeasureStringX(f, str)
    local px = x * s
    if align == "r" then px = px - w elseif align == "c" then px = px - w / 2 end
    local h = tm:getFontHeight(f); local py = y * s - math.max(0, (h - (size or 5) * s) / 2)
    self:drawText(str, math.floor(px), math.floor(py), c.r, c.g, c.b, c.a or 1, f)
end
-- speed indicator: three lit-segment groups + multiplier, or PAUSE
function ZeD_Watch:_speedInd(x, y, fg, dim, speed)
    if speed == 0 then self:_rect(x, y - 2, 2, 6, fg); self:_rect(x + 4, y - 2, 2, 6, fg); self:_text(x + 9, y - 2, "PAUSE", 5, fg, "l"); return end
    for i = 0, 2 do
        local lit = speed >= i + 1
        for k = 0, i do self:_rect(x + i * 11 + k * 4, y - 2, 2, 6, lit and fg or dim) end
    end
    self:_text(x + 36, y - 2, tostring(speed) .. "x", 5, fg, "l")
end
function ZeD_Watch:_hands(an, ti)
    local hourDeg = ((ti.hour % 12) + ti.min / 60) * 30
    local minDeg = ti.min * 6
    self:_run(an.cx, an.cy, hourDeg, 0, an.hour, an.color, 3)
    self:_run(an.cx, an.cy, minDeg, 0, an.min, an.color, 2)
    if an.lume then self:_run(an.cx, an.cy, hourDeg, 5, an.hour - 3, an.lume, 1); self:_run(an.cx, an.cy, minDeg, 8, an.min - 4, an.lume, 1) end
end
function ZeD_Watch:_hitAdd(id, x, y, w, h)
    local s = self._s
    self._hit[#self._hit + 1] = { id = id, x = math.floor(x * s), y = math.floor(y * s), w = math.floor(w * s), h = math.floor(h * s) }
end

function ZeD_Watch:_layout(frameW, frameH)
    local s = self:_scale()
    local w, h = math.floor(frameW * s), math.floor(frameH * s)
    local pn = self.playerNum
    local right = getPlayerScreenLeft(pn) + getPlayerScreenWidth(pn)
    local clock = UIManager.getClock()
    local x = right - w - math.floor(8 * s)
    -- Y anchors where the Java clock used to sit (it is parked off-screen, see prerender)
    local y = getPlayerScreenTop(pn) + (W._clockY or 10)
    if clock then x = math.min(x, clock:getX() + clock:getWidth() - w) end
    if self:getWidth() ~= w then self:setWidth(w) end
    if self:getHeight() ~= h then self:setHeight(h) end
    if self:getX() ~= x then self:setX(x) end
    if self:getY() ~= y then self:setY(y) end
    return w, h, s
end

function ZeD_Watch:prerender()
    local player = getSpecificPlayer(self.playerNum)
    if not player or (ISUIHandler and ISUIHandler.allUIVisible == false) then return end
    -- Park the Java clock and speed controls every frame. setVisible(false) is NOT enough in
    -- B42 (UIManager renders both regardless of the flag), so they also go off-screen. Java
    -- re-aligns their X every frame but leaves Y alone, so Y is the parking axis; the clock's
    -- original Y is remembered as the anchor for this watch.
    local clock = UIManager.getClock()
    if clock then
        local cy = clock:getY()
        if cy >= 0 then W._clockY = cy; pcall(clock.setY, clock, -4000) end
        if clock:isVisible() then pcall(clock.setVisible, clock, false) end
    end
    local sc = UIManager.getSpeedControls()
    if sc then
        if sc:getY() >= 0 then pcall(sc.setY, sc, -4000) end
        if sc:isVisible() then pcall(sc.setVisible, sc, false) end
    end

    local item = _wornWatch(player)
    local plateName, family = _plateFor(item)
    self._item = item; self._family = family
    self._hit = {}
    local speed = _speed()
    local ti = _timeInfo()
    if not item then
        -- no watch: the plain speed strip
        local fw, fh = 100, 22
        local w, h, s = self:_layout(fw, fh); self._s = s
        local T = ZeD.T
        self:_rect(0, 0, fw, fh, T.surf2); self:_rect(0, 0, fw, 1, T.border); self:_rect(0, fh - 1, fw, 1, T.border); self:_rect(0, 0, 1, fh, T.border); self:_rect(fw - 1, 0, 1, fh, T.border)
        local labels = { "||", ">", ">>", ">>>" }
        for i = 0, 3 do
            local on = speed == i
            local ac = T.accent
            self:_rect(4 + i * 24, 4, 22, 14, on and ac or T.surf3)
            self:_text(15 + i * 24, 8, labels[i + 1], 7, on and T.base or T.textDim, "c")
            self:_hitAdd("speed" .. i, 4 + i * 24, 4, 22, 14)
        end
        return
    end
    local A = PL[plateName]; if not A then return end
    local fw, fh = A.size.w, A.size.h
    local w, h, s = self:_layout(fw, fh); self._s = s
    local t = tex(TEXDIR .. plateName .. ".png")
    if t then self:drawTextureScaledAspect(t, 0, 0, w, h, 1, 1, 1, 1) end
    local armed = _safe(function() return item:isAlarmSet() end, false)
    local alarmHour = _safe(function() return item:getHour() end, 6) or 6
    local alarmMin = _safe(function() return item:getMinute() end, 0) or 0
    if family == "digital" then
        local L = A.lcd
        if self._setOpen then
            self:_text(L.set.title.x, L.set.title.y, "ALARM SET", 4, L.fg, "c")
            self:_text(L.set.value.x, L.set.value.y, string.format("%02d:%02d", alarmHour, alarmMin), 15, L.fg, "c")
            self:_text(L.set.hint.x, L.set.hint.y, "< -1H   +1H >", 3, L.dim, "c")
            self:_hitAdd("setdn", L.x, L.y, L.w / 2, L.h); self:_hitAdd("setup", L.x + L.w / 2, L.y, L.w / 2, L.h)
        else
            if ti.pm then self:_text(L.pm.x, L.pm.y, "P", 4, L.fg, "l") end
            self:_speedInd(L.speed.x, L.speed.y, L.fg, L.dim, speed)
            if armed then self:_text(L.alm.x, L.alm.y, "ALM", 4, L.fg, "r") end
            self:_text(L.time.x, L.time.y, ti.timeStr, 17, L.fg, "c")
            self:_text(L.day.x, L.day.y, ti.dow, 5, L.fg, "r")
            self:_text(L.date.x, L.date.y, tostring(ti.day), 5, L.fg, "r")
        end
        local kA, kS, kSp, kSt = A.keyAlarm, A.keySet, A.keySpeed, A.keyStart
        if self._setOpen then self:_rect(kS.x, kS.y, kS.w, kS.h, "#ffffff", 0.85) end
        if speed > 0 and kSp.mark then self:_rect(kSp.mark.x, kSp.mark.y, 4, 4, (A.runMark and A.runMark.c) or "#44EE44") end
        if speed == 0 then
            -- the plate prints START; cover it with the key fill and print STOP? No: paused shows START (press to run)
        else
            self:_rect(kSt.labelX - 14, kSt.labelY - 1, 28, 7, kSt.fill); self:_text(kSt.labelX, kSt.labelY, "STOP", 5, kSt.txt, "c")
        end
        self:_hitAdd("alarm", kA.x, kA.y, kA.w, kA.h); self:_hitAdd("set", kS.x, kS.y, kS.w, kS.h)
        self:_hitAdd("speed", kSp.x, kSp.y, kSp.w, kSp.h); self:_hitAdd("start", kSt.x, kSt.y, kSt.w, kSt.h)
    elseif family == "classic" then
        self:_hands(A.hands, ti)
        local L = A.lcd
        if self._setOpen then
            self:_text(L.x + L.w / 2, L.day.y, "ALM " .. string.format("%02d:%02d", alarmHour, alarmMin), 5, L.fg, "c")
            self:_text(L.x + L.w / 2, L.speed.y - 2, "< -1H  +1H >", 3, L.dim, "c")
            self:_hitAdd("setdn", L.x, L.y, L.w / 2, L.h); self:_hitAdd("setup", L.x + L.w / 2, L.y, L.w / 2, L.h)
        else
            self:_text(L.day.x, L.day.y, ti.dow, 4, L.fg, "l"); self:_text(L.date.x, L.date.y, ti.dateShort, 4, L.fg, "r")
            self:_speedInd(L.speed.x, L.speed.y, L.fg, L.dim, speed)
            if armed then self:_text(L.alm.x, L.alm.y, "ALM", 4, L.fg, "r") end
        end
        if armed and A.alarmDot then self:_rect(A.alarmDot.x, A.alarmDot.y, 4, 4, "#CC4444") end
        for id, name in pairs({ set = "pushSet", speed = "pushSpeed", alarm = "pushAlarm", start = "pushStart", crown = "crown" }) do
            local p = A[name]; if p then self:_hitAdd(id, p.x, p.y, p.w, p.h) end
        end
    else -- expensive
        self:_hands(A.hands, ti)
        if A.dateWin then self:_text(A.dateWin.x, A.dateWin.y, tostring(ti.day), 6, "#000000", "c") end
        if armed and A.alarmDot then self:_rect(A.alarmDot.x, A.alarmDot.y, 3, 3, "#CC4444") end
        local ch = A.chevrons
        if ch then
            if speed == 0 then self:_rect(ch.x + 34, ch.y - 2, 2, 5, ch.pause); self:_rect(ch.x + 38, ch.y - 2, 2, 5, ch.pause)
            else for i = 0, 2 do if speed >= i + 1 then for k = 0, i do self:_rect(ch.x + i * 11 + k * 4, ch.y - 2, 2, 5, ch.color) end end end end
        end
        if self._setOpen then self:_text(A.hands.cx, A.hands.cy + 4, "ALM " .. string.format("%02d:%02d", alarmHour, alarmMin), 5, "#141414", "c"); self:_hitAdd("setdn", A.hands.cx - 30, A.hands.cy, 30, 14); self:_hitAdd("setup", A.hands.cx, A.hands.cy, 30, 14) end
        for id, name in pairs({ speed = "pushSpeed", start = "pushStart", crown = "crown" }) do
            local p = A[name]; if p then self:_hitAdd(id, p.x, p.y, p.w, p.h) end
        end
    end
end
function ZeD_Watch:render() end

function ZeD_Watch:_act(id)
    local item = self._item
    if id:sub(1, 5) == "speed" and #id == 6 then _setSpeed(tonumber(id:sub(6))); return end   -- speed strip pills
    if id == "speed" then _actSpeed(); return end
    if id == "start" then _actStart(); return end
    if not item then return end
    if id == "alarm" then
        if self._setOpen then self._setOpen = false; return end
        pcall(function() item:setAlarmSet(not item:isAlarmSet()) end); return
    end
    if id == "crown" then
        if self._family == "expensive" or self._family == "classic" then self._setOpen = not self._setOpen; return end
    end
    if id == "set" then self._setOpen = not self._setOpen; return end
    if id == "setup" or id == "setdn" then
        local h = (_safe(function() return item:getHour() end, 6) or 6) + ((id == "setup") and 1 or -1)
        if h > 23 then h = 0 end; if h < 0 then h = 23 end
        pcall(function() item:setHour(h); item:setMinute(0) end)
        return
    end
end
function ZeD_Watch:onMouseDown(x, y)
    for _, hr in ipairs(self._hit or {}) do
        if x >= hr.x and x < hr.x + hr.w and y >= hr.y and y < hr.y + hr.h then
            pcall(function() getSoundManager():playUISound("UIActivateButton") end)
            local ok, err = pcall(self._act, self, hr.id)
            if not ok then print("[ZeD] Watch: action " .. tostring(hr.id) .. " failed: " .. tostring(err)) end
            return true
        end
    end
    return false
end

-- ---------------------------------------------------------------------------
-- Lifecycle
-- ---------------------------------------------------------------------------
function W.install()
    if W._instance then return W._instance end
    local inst = ZeD_Watch:new(0)
    inst:initialise()
    inst:addToUIManager()
    inst:setVisible(true)
    W._instance = inst
    print("[ZeD] Watch: v5 plate watch installed (Java clock + speed controls parked)")
    return inst
end
function W.getInstance() return W._instance end

Events.OnGameStart.Add(function() W._instance = nil; W.install() end)
